    // Simpler: if s.is_empty() { return "".to_string(); } else { let mut parts: Vec<&str> = s.split('\n').collect(); parts.reverse(); let mut joined = parts.join("\n"); // join doesn't add trailing, but original had trailing? For "a\nb\n", parts ["a","b",""], reversed ["","b","a"], joined "\nb\na" (no trailing). To get "\nb\na\n" (with trailing), need to push "\n".
    // For "a\nb" (no trailing), parts ["a","b"], reversed ["b","a"], joined "b\na" (no trailing), need "b\na\n" (with trailing). So always push "\n" when s non-empty?
    // What about "a" (single line, no newline)? Parts ["a"], reversed ["a"], joined "a", + "\n" => "a\n". Without reverse, "a" (no newline) batch prints "a\n" (adds newline). With reverse, same? Likely.
    // So: if s.is_empty() { "" } else { join + "\n" }? But what about s == "\n" (single newline)? Parts ["",""], reversed ["",""], joined "\n" (one separator, 2 parts => "\n"), + "\n" => "\n\n"? Without reverse, "\n" batch would be "\n\n" (output "\n" + blank "\n")? With reverse, "\n" reversed? Parts ["",""] reversed same, joined "\n", + "\n" => "\n\n" same. Good.
    // Let's implement that.
    if s.is_empty() {
        return "".to_string();
