#[derive(Debug)]
enum DiffOp {
    Equal(String),
    Delete(String),
    Insert(String),
    Replace(Vec<String>, Vec<String>),
}

fn diff_lines(a: &[String], b: &[String]) -> Vec<DiffOp> {
    // Simple Myers/LCS implementation for small inputs
    // Use DP for LCS
    let n = a.len();
    let m = b.len();
    // DP table
    let mut dp = vec![vec![0; m+1]; n+1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            if a[i] == b[j] {
                dp[i][j] = dp[i+1][j+1] + 1;
            } else {
                dp[i][j] = std::cmp::max(dp[i+1][j], dp[i][j+1]);
            }
        }
    }
    // Backtrack to get ops, grouping deletes/inserts into replaces?
    let mut ops: Vec<DiffOp> = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < n && j < m {
        if a[i] == b[j] {
            ops.push(DiffOp::Equal(a[i].clone()));
            i+=1; j+=1;
        } else if dp[i+1][j] >= dp[i][j+1] {
            // Delete a[i]
            // Collect consecutive deletes and inserts as replace?
            let mut dels = vec![a[i].clone()];
            i+=1;
            // Look ahead: if next is insert, collect?
            // For simplicity, collect all consecutive deletes
            while i < n && (j >= m || a[i] != b[j]) && dp[i+1][j] >= dp[i][j+1] {
                // Check if it's delete vs insert? This logic is messy.
                // Simpler: just push single Delete for now, handle Replace later by merging?
                // Let's just push Delete and continue; merging to Replace will be done in post-process?
                // Actually, to get Replace for single line change, we need to pair Delete+Insert.
                // Our DP will produce Delete then Insert for replace (since a[i]!=b[j], it will delete a[i], then next iteration a[i+1]==b[j]? Or insert?
                // Let's just push Delete and continue loop (which will then handle Insert)
                break;
            }
            // Push dels as Deletes (for now single)
            for d in dels {
                ops.push(DiffOp::Delete(d));
            }
        } else {
            // Insert b[j]
            ops.push(DiffOp::Insert(b[j].clone()));
            j+=1;
        }
    }
    while i < n {
        ops.push(DiffOp::Delete(a[i].clone()));
        i+=1;
    }
    while j < m {
        ops.push(DiffOp::Insert(b[j].clone()));
        j+=1;
    }
    // Post-process: merge consecutive Delete(s) + Insert(s) into Replace?
    // As observed, single line change "line2" -> "line2 changed" should be Replace (Delete+Insert paired with word diff), not separate Delete and Insert.
    // Our current will produce Delete("line2") then Insert("line2 changed") consecutively. Merge them into Replace.
    let mut merged: Vec<DiffOp> = Vec::new();
    let mut idx = 0;
    while idx < ops.len() {
        // Collect deletes
        let mut dels = Vec::new();
        while idx < ops.len() {
            if let DiffOp::Delete(s) = &ops[idx] {
                dels.push(s.clone());
                idx+=1;
            } else { break; }
        }
        let mut inss = Vec::new();
        while idx < ops.len() {
            if let DiffOp::Insert(s) = &ops[idx] {
                inss.push(s.clone());
                idx+=1;
            } else { break; }
        }
        if !dels.is_empty() || !inss.is_empty() {
            if !dels.is_empty() && !inss.is_empty() {
                merged.push(DiffOp::Replace(dels, inss));
            } else if !dels.is_empty() {
                for d in dels { merged.push(DiffOp::Delete(d)); }
            } else {
                for ins in inss { merged.push(DiffOp::Insert(ins)); }
            }
        } else {
            // Equal
            if let DiffOp::Equal(s) = &ops[idx] {
                merged.push(DiffOp::Equal(s.clone()));
                idx+=1;
            } else {
                // Should not happen
                idx+=1;
            }
        }
    }
    merged
}

