        "stdout" => curr.stdout.clone(),
        "stderr" => curr.stderr.clone(),
        _ => curr.output.clone(), // output = stderr+stdout? Actually need to determine how output is constructed: stderr+stdout? Or stdout+stderr?
        // From earlier, output is stderr+stdout (ERR then OUT) most of time, but occasionally flips due to race.
        // For our implementation, we will construct output as stderr+stdout deterministically (stderr first).
        // Good.
    };
    let prev_text = match output_mode {
        "stdout" => prev.stdout.clone(),
        "stderr" => prev.stderr.clone(),
        _ => prev.output.clone(),
    };
    // Handle reverse: reverse lines? As observed, reverse splits by "\n" and reverses, then joins?
    // For "a\nb\nc\n" -> ["a","b","c",""] reversed -> ["","c","b","a"] joined with "\n" -> "\nc\nb\na" + "\n"? Actually need to replicate exactly.
    // Let's implement: split by '\n' (preserving trailing empty?), reverse, join with '\n', then ensure trailing newline handling?
    // For normal batch without reverse, display is curr_text as is (with its newlines), plus extra handling for blank line (in print function).
    // For reverse, display is reversed version of curr_text (and prev_text for diff? Diff should be on reversed? As observed, reverse+diff diffs reversed outputs. Good.)
    // So apply reverse to both curr and prev before diff?
    let (curr_proc, prev_proc) = if reverse {
        (reverse_text(&curr_text), reverse_text(&prev_text))
    } else {
        (curr_text, prev_text)
    };

    // Handle differences
    let diff_mode = differences.as_deref().unwrap_or("none");
    // "none" means no diff (also default when -d not provided? What is default? When -d not provided, differences None => none. When -d provided without value, Some("watch"). When -d none explicitly, Some("none") => none.
    // So treat None as none, Some("none") as none.
    if diff_mode == "none" {
        // No diff: return curr_proc as is (with line numbers if needed? Line numbers applied later? Or here?)
        // Line numbers: if enabled, format with numbers and colors, no extra blank (as observed)
        if line_number {
            return format_with_line_numbers(&curr_proc, diff_mode, false);
        } else {
            return curr_proc;
        }
    } else if diff_mode == "watch" {
        // Watch diff: highlight from first diff char to end of line
        let out = format_watch_diff(&prev_proc, &curr_proc);
        if line_number {
            // How does line-number + watch diff work? Need to test. We tested line-number + line diff, but not + watch.
            // Let's assume similar: numbers with colors? Need to test.
            return format_watch_with_line_numbers(&prev_proc, &curr_proc);
        } else {
            return out;
        }
    } else if diff_mode == "line" {
        let out = format_line_diff(&prev_proc, &curr_proc, diff_output_only, false);
        if line_number {
            return format_line_diff_with_numbers(&prev_proc, &curr_proc, diff_output_only);
        } else {
            return out;
        }
    } else if diff_mode == "word" {
