#[derive(Debug)]
enum TokenOp {
    Equal(String),
    Delete(String),
    Insert(String),
    Replace(Vec<String>, Vec<String>),
}

fn diff_tokens(a: &[String], b: &[String]) -> Vec<TokenOp> {
    // Similar LCS as diff_lines
    let n = a.len();
    let m = b.len();
    let mut dp = vec![vec![0; m+1]; n+1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            if a[i] == b[j] {
                dp[i][j] = dp[i+1][j+1] + 1;
            } else {
                dp[i][j] = std::cmp::max(dp[i+1][j], dp[i][j+1]);
            }
        }
    }
    let mut ops = Vec::new();
    let mut i=0; let mut j=0;
    while i<n && j<m {
        if a[i]==b[j] {
            ops.push(TokenOp::Equal(a[i].clone()));
            i+=1; j+=1;
        } else if dp[i+1][j] >= dp[i][j+1] {
            ops.push(TokenOp::Delete(a[i].clone()));
            i+=1;
        } else {
            ops.push(TokenOp::Insert(b[j].clone()));
            j+=1;
        }
    }
    while i<n { ops.push(TokenOp::Delete(a[i].clone())); i+=1; }
    while j<m { ops.push(TokenOp::Insert(b[j].clone())); j+=1; }
    // Merge Delete+Insert into Replace? For word diff, replacement of single word "b"->"c" would be Delete("b") then Insert("c") consecutively. Should we merge into Replace? Our earlier handling for line diff merged. For word diff, we handle Delete and Insert separately (highlight each). Merging into Replace would still highlight both, same. So no need to merge? But for trailing empty logic, need to know last op is non-Equal. Whether Delete+Insert separate or Replace merged, last is still non-Equal. Good. So no merge needed for word.
    // But for simplicity, keep as is (no Replace).
    // Actually our TokenOp::Replace is unused then. Let's just return ops with Delete/Insert/Equal.
    ops
}

